<script>
 import {onMount} from 'svelte';import {teamUser} from '../api';import {chooseDirectory,useBrowserDownloads,directoryName,saveFileAs,saveNewFiles,restoreDirectory,pendingDownloads,confirmSaved} from '../local-downloads';let folder=$state(directoryName()),pending=$state([]);let open=$state(false),files=$state([]),error=$state(''),status=$state('');
 async function downloads(e){open=true;status='';error=e?.detail?.message||'';try{const r=await fetch('/api/files',{cache:'no-store'});if(r.status===401){location.reload();return;}if(!r.ok)throw Error("下载列表暂时不可用，请刷新重试。");files=(await r.json()).files;}catch(e){error=e.message;}}
 async function logout(){try{const r=await fetch('/api/team/logout',{method:'POST',headers:{'X-Edge-IPC':'1'}});if(!r.ok)throw Error('退出登录失败，请重试。');location.reload();}catch(e){error=e.message;open=true;}}
 onMount(()=>{if(!teamUser)return;restoreDirectory().then(()=>saveNewFiles()).catch(e=>error=e.message);const timer=setInterval(()=>saveNewFiles().catch(e=>{error=e.message;open=true;}),4000);window.addEventListener('team-downloads',downloads);const update=()=>{folder=directoryName();pending=pendingDownloads();};const done=()=>{update();if(open)downloads();};window.addEventListener('team-directory',update);window.addEventListener('team-download-state',update);window.addEventListener('team-save-complete',done);return()=>{clearInterval(timer);window.removeEventListener('team-downloads',downloads);window.removeEventListener('team-directory',update);window.removeEventListener('team-download-state',update);window.removeEventListener('team-save-complete',done);};});
 async function confirm(f){try{if(await confirmSaved(f))await downloads();}catch(e){error=e.message;}}

 async function choose(){try{await chooseDirectory();folder=directoryName();}catch(e){error=e.message;}}
 async function save(f){try{const result=await saveFileAs(f);if(result?.saved)await downloads();else pending=pendingDownloads();}catch(e){error=e.message;}}
</script>
{#if teamUser}<div class="team-account"><span>{teamUser.username}</span><button onclick={downloads}>下载文件</button><button onclick={logout}>退出登录</button></div>{#if open}<div class="team-downloads" role="dialog" aria-label="我的下载文件"><header><h2>我的下载文件</h2><button onclick={()=>open=false} aria-label="关闭下载列表">×</button></header>{#if error}<p role="alert">{error}</p>{/if}{#if status}<p role="status">{status}</p>{/if}<button class="line-button" onclick={choose}>选择本机保存文件夹</button><button class="line-button" onclick={async()=>{await useBrowserDownloads();folder=directoryName();status=files.length?'已切换为浏览器另存为，请点击下方文件名选择保存位置。':'已切换为浏览器另存为。当前暂无文件，请先在导出页导出图片。';}}>切换为浏览器另存为</button><p>{folder?`结果自动保存到：${folder}；校验成功后清理主机副本`:'点击图片文件可另存为到下载或桌面。选择普通文件夹可自动保存。'}</p><p class="hint">浏览器可能禁止选择整个桌面或下载文件夹；请点击下方文件使用“另存为”。</p><p class="hint">仅同事工作区使用临时存储。未保存的图片保留 24 小时。保存并清理后，再次编辑需要重新导入。</p>{#each files as f}<a href={f.url} download={f.name} onclick={e=>{e.preventDefault();save(f);}}>另存为 · {f.name}<small>{Math.ceil(f.bytes/1000)} KB</small></a>{#if f.expiresAt}<small>保留至 {new Date(f.expiresAt*1000).toLocaleString('zh-CN')}</small>{/if}{#if pending.includes(f.url)}<button class="line-button" onclick={()=>confirm(f)}>已保存，清理主机</button>{/if}{/each}{#if !files.length}<p>暂无导出文件。</p>{/if}</div>{/if}{/if}
